    ],
    "dv": {
      "description": "Mortgage application approval. Binary indicator used as the outcome: 1 = accepted, 0 = denied.",
      "columns": [
        "accept"
      ]
    },
    "controls": [
      {
        "description": "Applicant race: 1 = Black, 0 = non-Black. Controls for racial differences in approval.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "black"
        ]
      },
      {
        "description": "Self-employment status: 1 = self-employed, 0 = not self-employed.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "self_employed"
        ]
      },
      {
        "description": "Marital status: 1 = married, 0 = not married.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "married"
        ]
      },
      {
        "description": "History of bad credit: 1 = has bad history, 0 = no bad history.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "bad_history"
        ]
      },
      {
        "description": "Applicant mortgage credit score (standardized). Continuous control; original column mortgage_credit is standardized to mortgage_credit_z.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "mortgage_credit_z"
        ]
      },
      {
        "description": "Applicant consumer credit score (standardized). Continuous control; original column consumer_credit is standardized to consumer_credit_z.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "consumer_credit_z"
        ]
      },
      {
        "description": "Total debt payments to income ratio (PI_ratio), standardized.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "PI_ratio_z"
        ]
      },
      {
        "description": "Loan-to-value ratio, standardized.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "loan_to_value_z"
        ]
      },
      {
        "description": "Housing expense as a ratio of income (standardized).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "housing_expense_ratio_z"
        ]
      },
      {
        "description": "Occupation code (standardized). Controls for occupation differences in approval.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "occupation_z"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    # Work on a copy\n    df = df.copy()\n\n    # Columns required for the analysis\n    required_cols = [\n        'accept',  # dependent variable\n        'female',  # independent variable\n        'black', 'self_employed', 'married', 'bad_history',  # binary controls\n        'mortgage_credit', 'consumer_credit', 'PI_ratio', 'loan_to_value', 'housing_expense_ratio', 'occupation'\n    ]\n\n    # Keep only required columns (drop extras)\n    df = df.loc[:, [c for c in required_cols if c in df.columns]]\n\n    # Drop rows with missing values in any required column\n    df = df.dropna(subset=[c for c in required_cols if c in df.columns])\n\n    # Ensure binary columns are integers (0/1)\n    for bcol in ['accept', 'female', 'black', 'self_employed', 'married', 'bad_history']:\n        if bcol in df.columns:\n            # Coerce to numeric then to int (safe conversion)\n            df[bcol] = pd.to_numeric(df[bcol], errors='coerce').astype(int)\n\n    # Ensure continuous columns are numeric\n    cont_cols = ['mortgage_credit', 'consumer_credit', 'PI_ratio', 'loan_to_value', 'housing_expense_ratio', 'occupation']\n    for c in cont_cols:\n        if c in df.columns:\n            df[c] = pd.to_numeric(df[c], errors='coerce')\n\n    # Drop any rows that became NaN after coercion\n    df = df.dropna(subset=[c for c in required_cols if c in df.columns])\n\n    # Standardize continuous predictors (z-score) and store with _z suffix\n    # Use population std (ddof=0) for consistency\n    for c in cont_cols:\n        if c in df.columns:\n            zcol = f\"{c}_z\"\n            mean = df[c].mean()\n            std = df[c].std(ddof=0)\n            # If std is zero (constant), create zeros to avoid division by zero\n            if std == 0 or np.isnan(std):\n                df[zcol] = 0.0\n            else:\n                df[zcol] = (df[c] - mean) / std\n\n    # Final dataframe contains the dependent variable, the independent variable, and standardized controls\n    final_cols = [\n        'accept', 'female', 'black', 'self_employed', 'married', 'bad_history',\n        'mortgage_credit_z', 'consumer_credit_z', 'PI_ratio_z', 'loan_to_value_z', 'housing_expense_ratio_z', 'occupation_z'\n    ]\n\n    # Keep only columns that exist (in case some expected cols were not in the original df)\n    final_cols = [c for c in final_cols if c in df.columns]\n    df = df.loc[:, final_cols]\n\n    # Return transformed dataframe\n    return df\n",
  "m_code": "def model(df: pd.DataFrame) -> Any:\n    # Build logistic regression predicting acceptance (approval) from gender and controls\n    import statsmodels.api as sm\n\n    # Ensure the dataframe contains the columns we expect\n    predictors = [\n        'female', 'black', 'self_employed', 'married', 'bad_history',\n        'mortgage_credit_z', 'consumer_credit_z', 'PI_ratio_z', 'loan_to_value_z', 'housing_expense_ratio_z', 'occupation_z'\n    ]\n    predictors = [p for p in predictors if p in df.columns]\n\n    # Dependent variable\n    if 'accept' not in df.columns:\n        raise ValueError(\"Transformed dataframe must contain 'accept' column as the dependent variable.\")\n\n    y = df['accept']\n    X = df[predictors]\n\n    # Add intercept\n    X = sm.add_constant(X, has_constant='add')\n\n    # Fit logistic regression (maximum likelihood)\n    logit_model = sm.Logit(y, X)\n    results = logit_model.fit(disp=False)\n\n    # Return the fitted results object (user can call .summary(), .params, etc.)\n    return results\n"
}

